#!/usr/bin/env bash
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
target="${1:-$root/deploy/docker/.env}"

if ! command -v openssl >/dev/null 2>&1; then
  echo "openssl is required to generate RunnerHub secrets" >&2
  exit 1
fi

if [ -e "$target" ]; then
  echo "$target already exists; refusing to overwrite it" >&2
  exit 1
fi

mkdir -p "$(dirname "$target")"
umask 077

enrollment="$(openssl rand -hex 32)"
agent_secret="$(openssl rand -hex 32)"
admin_key="$(openssl rand -hex 32)"
scaleset_key="$(openssl rand -hex 32)"

cat >"$target" <<EOF
# Generated by scripts/init-docker-env.sh.
# Fill in the four GitHub values before running scripts/start-docker.sh.

RUNNERHUB_ENROLLMENT_TOKEN=$enrollment
RUNNERHUB_AGENT_SECRET=$agent_secret
RUNNERHUB_ADMIN_KEY=$admin_key
RUNNERHUB_SCALESET_KEY=$scaleset_key
RUNNERHUB_API_KEYS=$admin_key:admin:local-admin,$scaleset_key:operator:scaleset-listener

RUNNERHUB_GITHUB_APP_ISSUER=REPLACE_WITH_GITHUB_APP_CLIENT_ID
RUNNERHUB_GITHUB_APP_INSTALLATION_ID=REPLACE_WITH_INSTALLATION_ID
RUNNERHUB_GITHUB_APP_PRIVATE_KEY_FILE=/absolute/path/to/runnerhub-github-app.pem
RUNNERHUB_GITHUB_URL=https://github.com/OWNER/REPOSITORY

# Default automatic repository-scoped pool/scale-set settings.
RUNNERHUB_POOL_ID=pool-docker
RUNNERHUB_SCALESET_NAME=runnerhub
RUNNERHUB_MIN_RUNNERS=0
RUNNERHUB_MAX_RUNNERS=2

# Refresh the official ephemeral runner image before each worker starts.
RUNNERHUB_DOCKER_PULL_POLICY=always

# Optional overrides.
# RUNNERHUB_GITHUB_API_URL=https://api.github.com
# RUNNERHUB_HOST_NAME=my-runner-host
# RUNNERHUB_ALLOWED_IMAGES=ghcr.io/actions/actions-runner:latest
# RUNNERHUB_RUNNER_IMAGE=ghcr.io/actions/actions-runner:latest
# RUNNERHUB_RUNNER_GROUP=
# RUNNERHUB_RUNNER_GROUP_ID=1
EOF

chmod 600 "$target"
printf 'Created %s with generated RunnerHub secrets.\n' "$target"
printf 'Fill in the GitHub App client ID, installation ID, PEM path, and repository URL.\n'
printf 'Then run: bash scripts/start-docker.sh %s\n' "$target"
